import { getToken } from './storage';

// API client for backend communication
const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000/api';

// Generic API call function
export const apiCall = async (endpoint, method = 'GET', data = null) => {
  const token = getToken();
  const isFormData = typeof FormData !== 'undefined' && data instanceof FormData;
  const options = {
    method,
    headers: {
      ...(isFormData ? {} : { 'Content-Type': 'application/json' }),
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
    },
  };

  if (data) {
    options.body = isFormData ? data : JSON.stringify(data);
  }

  try {
    const response = await fetch(`${API_URL}${endpoint}`, options);

    if (!response.ok) {
      const errorData = await response.json();
      throw new Error(errorData.error || `HTTP ${response.status}`);
    }

    return await response.json();
  } catch (error) {
    console.error('API Error:', error.message);
    throw error;
  }
};

// Auth endpoints
export const authAPI = {
  login: (email, password) =>
    apiCall('/auth/login', 'POST', { email, password }),

  signup: (name, email, password, role = 'student') =>
    apiCall('/auth/signup', 'POST', { name, email, password, role }),

  me: () =>
    apiCall('/auth/me', 'GET'),

  getAllUsers: () =>
    apiCall('/auth/users', 'GET'),
};

// Request endpoints
export const requestAPI = {
  getAdminDashboard: () =>
    apiCall('/requests/dashboard/admin', 'GET'),

  getStudentDashboard: () =>
    apiCall('/requests/dashboard/student', 'GET'),

  getAllRequests: () =>
    apiCall('/requests', 'GET'),

  getUserRequests: (studentId) =>
    apiCall(`/requests/user/${studentId}`, 'GET'),

  getRequestById: (id) =>
    apiCall(`/requests/${id}`, 'GET'),

  createRequest: (studentId, studentName, category, title, description, priority = 'Medium') =>
    apiCall('/requests', 'POST', {
      studentId,
      studentName,
      category,
      title,
      description,
      priority,
    }),

  uploadAttachments: (id, files) => {
    const formData = new FormData();
    files.forEach((file) => {
      formData.append('files', file);
    });
    return apiCall(`/requests/${id}/attachments`, 'POST', formData);
  },

  updateRequest: (id, updates) =>
    apiCall(`/requests/${id}`, 'PUT', updates),
};
